// Grafana webhook payload -> one spoken sentence per FIRING alert.
// Language for the voice note: ALERT_LANG = en | hi | mr (default en).
const body = $input.first().json.body || $input.first().json;
const lang = ['en', 'hi', 'mr'].includes($env.ALERT_LANG) ? $env.ALERT_LANG : 'en';
const out = [];
for (const a of (body.alerts || [])) {
  if (a.status !== 'firing') continue;
  const labels = a.labels || {};
  const values = a.values || {};
  const kind = labels.kind || labels.alertname;
  let text;
  if (kind === 'device_silent' || labels.alertname === 'DeviceSilent') {
    const dev = (labels.device_id || 'a device');
    const spoken = dev.replace('-', ' ');
    const mins = Math.max(1, Math.round((Number(values.B) || 120) / 60));
    text = {
      en: `Alert: ${spoken} has been offline for ${mins} minutes.`,
      hi: `चेतावनी: ${spoken} ${mins} मिनट से ऑफ़लाइन है।`,
      mr: `सूचना: ${spoken} ${mins} मिनिटांपासून ऑफलाइन आहे.`,
    }[lang];
  } else if (kind === 'sla_breach' || labels.alertname === 'PaymentSLABreaches') {
    const n = Math.round(Number(values.B) || 0);
    text = {
      en: `Alert: ${n} payment SLA breaches in the last 5 minutes.`,
      hi: `चेतावनी: पिछले 5 मिनट में ${n} पेमेंट एसएलए उल्लंघन हुए।`,
      mr: `सूचना: गेल्या 5 मिनिटांत ${n} पेमेंट एसएलए उल्लंघने झाली.`,
    }[lang];
  } else {
    text = (a.annotations && a.annotations.summary) || `Alert ${labels.alertname} is firing.`;
  }
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const who = (labels.device_id || labels.alertname || 'alert').replace(/[^a-zA-Z0-9_-]/g, '_');
  out.push({ json: { text, lang, alertname: labels.alertname, device: labels.device_id || null,
                     startsAt: a.startsAt, receivedAt: new Date().toISOString(),
                     filename: `${stamp}_${who}.ogg` } });
}
return out;

// Append one JSON line per delivered alert to /alerts_out/alerts.log (the "mock Telegram" log).
const fs = require('fs');
const results = [];
for (const item of $input.all()) {
  const src = $('Build sentence').all()[results.length] || { json: {} };
  const line = { ...src.json, delivered: 'file', path: `/alerts_out/${src.json.filename}`,
                 telegram: 'not configured (TELEGRAM_BOT_TOKEN/TELEGRAM_CHAT_ID empty): saved to alerts_out instead',
                 savedAt: new Date().toISOString() };
  fs.appendFileSync('/alerts_out/alerts.log', JSON.stringify(line) + '\n');
  results.push({ json: line });
}
return results;
